def transform(grid):
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for row in out:
        last = -1
        for j, value in enumerate(row):
            if value != bg:
                last = j
        if last >= 0:
            for j in range(last + 1, len(row)):
                row[j] = 1
    return out
